 86		// AC: @ui-task-board ac-1
 87		it('places blocked tasks in In Progress column', () => {
 88			const tasks = [makeTask({ status: 'blocked' })];
 89			const columns = distributeToColumns(tasks);
 90			const inProgress = columns.find((c) => c.id === 'in_progress')!;
 91			expect(inProgress.tasks).toHaveLength(1);
 92			expect(inProgress.tasks[0].status).toBe('blocked');
 93		});
 94	
 95		// AC: @ui-task-board ac-1
 96		it('places cancelled tasks in Done column', () => {
 97			const tasks = [makeTask({ status: 'cancelled' })];
 98			const columns = distributeToColumns(tasks);
 99			const done = columns.find((c) => c.id === 'done')!;
100			expect(done.tasks).toHaveLength(1);
101			expect(done.tasks[0].status).toBe('cancelled');
102		});
103	
104		// AC: @ui-task-board ac-1
105		it('sorts columns by priority (lower number = higher priority)', () => {
106			const tasks = [
107				makeTask({ status: 'pending', automation: 'eligible', priority: 5 }),
108				makeTask({ status: 'pending', automation: 'eligible', priority: 1 }),
109				makeTask({ status: 'pending', automation: 'eligible', priority: 3 })
110			];
111			const columns = distributeToColumns(tasks);
112			const ready = columns.find((c) => c.id === 'ready')!;
113			expect(ready.tasks[0].priority).toBe(1);
114			expect(ready.tasks[1].priority).toBe(3);
115			expect(ready.tasks[2].priority).toBe(5);
116		});
117	
118		// AC: @ui-task-board ac-1
119		it('returns all five columns even when empty', () => {
120			const columns = distributeToColumns([]);
121			expect(columns).toHaveLength(5);
122			expect(columns.map((c) => c.id)).toEqual([
123				'backlog',
124				'ready',
125				'in_progress',
126				'review',
127				'done'
128			]);
129		});
130	});
131	
132	describe('getStatusClasses', () => {
133		// AC: @ui-task-board ac-2
134		it('returns correct classes for all known statuses', () => {
135			const statuses = [
136				'pending',
137				'in_progress',
138				'pending_review',
139				'needs_work',
140				'completed',
141				'blocked',
142				'cancelled'
143			];
144			for (const status of statuses) {
145				const result = getStatusClasses(status);
