  2	 * Alignment tracking between specs and tasks.
  3	 *
  4	 * Provides bidirectional mapping from spec items to implementing tasks,
  5	 * and detects alignment issues like orphaned specs or stale implementation status.
  6	 */
  7	
  8	import type { ImplementationStatus } from "../schema/index.js";
  9	import type { ReferenceIndex } from "./refs.js";
 10	import type { KspecContext, LoadedSpecItem, LoadedTask } from "./yaml.js";
 11	import { updateSpecItem } from "./yaml.js";
 12	
 13	// ============================================================
 14	// TYPES
 15	// ============================================================
 16	
 17	/**
 18	 * Summary of a spec item's implementation status based on linked tasks
 19	 */
 20	export interface SpecImplementationSummary {
 21	  specUlid: string;
 22	  specTitle: string;
 23	  currentStatus: ImplementationStatus;
 24	  expectedStatus: ImplementationStatus;
 25	  linkedTasks: LinkedTaskSummary[];
 26	  isAligned: boolean;
 27	}
 28	
 29	/**
